"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["87089"],{1839(o){o.exports=JSON.parse('{"registro":{"codigo":"uniplus.configuracao.tipo_etapa.conceitos_admitidos_obrigatorio","status":422,"titulo":"Declara\xe7\xe3o dos conceitos admitidos pelo tipo de etapa \xe9 obrigat\xf3ria"},"descricao":{"codigo":"uniplus.configuracao.tipo_etapa.conceitos_admitidos_obrigatorio","requisitos":[],"oQueAconteceu":["O tipo de etapa chegou sem a declara\xe7\xe3o dos conceitos admitidos: o campo `conceitosAdmitidos` veio ausente ou nulo. A declara\xe7\xe3o \xe9 obrigat\xf3ria para que fique expl\xedcito que a lista n\xe3o foi esquecida. Uma lista **vazia** \xe9 v\xe1lida e significa que o tipo de etapa n\xe3o admite nenhum conceito. Na atualiza\xe7\xe3o o campo tamb\xe9m precisa ser enviado, porque a lista \xe9 substitu\xedda por inteiro. Nada foi gravado.","Na atualiza\xe7\xe3o, esta confer\xeancia vem antes de o tipo de etapa ser procurado: com o conte\xfado nessa condi\xe7\xe3o a resposta \xe9 esta, mesmo que o identificador n\xe3o exista. O [404 de tipo de etapa n\xe3o encontrado](/erros/uniplus.configuracao.tipo_etapa.nao_encontrado) s\xf3 prevalece quando os campos e os conceitos admitidos s\xe3o v\xe1lidos."],"comoResolver":["Envie `conceitosAdmitidos` com os c\xf3digos dos tipos de conceito admitidos, ou com `[]` se o tipo de etapa n\xe3o admite nenhum."],"ondeAparece":["Cria\xe7\xe3o de um tipo de etapa (POST /api/configuracao/admin/tipos-etapa)","Atualiza\xe7\xe3o de um tipo de etapa (PUT /api/configuracao/admin/tipos-etapa/`{id}`), antes de o tipo de etapa ser procurado"]},"modulo":{"id":"configuracao","nome":"Configura\xe7\xe3o","assunto":"Tipo etapa"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"0258f07cac6c9b7f9d70290a4b0385549eb99572"}}')}}]);